338	    private function encodeMp4(string $input, string $output, array $def): void
339	    {
340	        $ffmpeg = $this->ffmpegBinary();
341	        $resolution = (string) ($def['resolution'] ?? '1280x720');
342	        [$width, $height] = array_map('intval', explode('x', $resolution, 2));
343	        $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
344	        $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
345	
346	        // Scale to fit within resolution bounds while maintaining aspect ratio.
347	        // The scale filter uses -2 to keep dimensions divisible by 2 (required by libx264).
348	        $scaleFilter = "scale='if(gt(iw,{$width}),{$width},-2)':'if(gt(ih,{$height}),{$height},-2)'";
349	
350	        $cmd = sprintf(
351	            '%s -y -i %s -vf %s -c:v libx264 -b:v %dk -maxrate %dk -bufsize %dk '
352	            .'-profile:v main -level 4.0 -movflags +faststart '
353	            .'-c:a aac -b:a %dk -ar 44100 %s 2>&1',
354	            escapeshellcmd($ffmpeg),
355	            escapeshellarg($input),
356	            escapeshellarg($scaleFilter),
357	            $videoBitrate,
358	            (int) ($videoBitrate * 1.5),
359	            (int) ($videoBitrate * 2),
360	            $audioBitrate,
361	            escapeshellarg($output),
362	        );
363	
364	        $output_str = $this->runCommand($cmd, $exitCode);
365	
366	        if ($exitCode !== 0) {
367	            throw new \RuntimeException("ffmpeg MP4 encoding failed (exit {$exitCode}): {$output_str}");
368	        }
369	    }
370	
371	    private function packageHls(string $mp4Input, string $playlistOutput): void
372	    {
373	        $ffmpeg = $this->ffmpegBinary();
374	        $outputDir = dirname($playlistOutput);
375	        $segmentPattern = $outputDir.'/seg_%03d.ts';
376	
377	        $cmd = sprintf(
378	            '%s -y -i %s -c copy -f hls -hls_time 6 -hls_playlist_type vod '
379	            .'-hls_segment_filename %s %s 2>&1',
380	            escapeshellcmd($ffmpeg),
381	            escapeshellarg($mp4Input),
382	            escapeshellarg($segmentPattern),
383	            escapeshellarg($playlistOutput),
384	        );
385	
386	        $output = $this->runCommand($cmd, $exitCode);
387	
388	        if ($exitCode !== 0) {
389	            throw new \RuntimeException("ffmpeg HLS packaging failed (exit {$exitCode}): {$output}");
390	        }
391	    }
392	
393	    private function extractPoster(string $input, string $output): void
394	    {
395	        $ffmpeg = $this->ffmpegBinary();
396	
397	        $cmd = sprintf(
398	            '%s -y -i %s -ss 00:00:01 -frames:v 1 -q:v 3 %s 2>&1',
399	            escapeshellcmd($ffmpeg),
400	            escapeshellarg($input),
401	            escapeshellarg($output),
402	        );
403	
404	        $outputStr = $this->runCommand($cmd, $exitCode);
405	
406	        if ($exitCode !== 0 || ! file_exists($output)) {
407	            // Non-fatal: try frame at 0s as fallback
408	            $cmd2 = sprintf(
409	                '%s -y -i %s -frames:v 1 -q:v 3 %s 2>&1',
410	                escapeshellcmd($ffmpeg),
411	                escapeshellarg($input),
412	                escapeshellarg($output),
413	            );
414	            $this->runCommand($cmd2, $exitCode2);
415	
416	            if ($exitCode2 !== 0 || ! file_exists($output)) {
417	                Log::warning('VideoVariantService: could not extract poster frame.', [
418	                    'error' => $outputStr,
419	                ]);
420	                // Create a 1-byte placeholder so downstream code doesn't fail
421	                file_put_contents($output, '');
422	            }
423	        }
424	    }
