426	    /**
427	     * Build the adaptive (master) HLS playlist content.
428	     *
429	     * @param  array<string, array<string, mixed>>  $variantDefs
430	     */
431	    private function buildAdaptivePlaylist(array $variantDefs): string
432	    {
433	        $lines = ['#EXTM3U'];
434	
435	        foreach ($variantDefs as $variantKey => $def) {
436	            // Guard against config values containing newlines or special chars
437	            // that would corrupt the line-based M3U8 format.
438	            if (! preg_match('/^[a-zA-Z0-9_-]+$/', (string) $variantKey)) {
439	                throw new \RuntimeException("Invalid video variant key: {$variantKey}");
440	            }
441	
442	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
443	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
444	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
445	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
446	
447	            // Resolution must be WxH (digits only) — e.g. 1280x720, 1920X1080.
448	            if (! preg_match('/^\d+X\d+$/', $resolution)) {
449	                throw new \RuntimeException("Invalid video resolution for variant '{$variantKey}': {$resolution}");
450	            }
451	
452	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
453	            $lines[] = "{$variantKey}/playlist.m3u8";
454	        }
455	
456	        return implode("\n", $lines)."\n";
457	    }
458	
459	    private function extractDurationMs(array $probe): int
460	    {
461	        $duration = $probe['format']['duration'] ?? null;
462	        if ($duration === null) {
463	            // Fall back to the first video stream
464	            foreach ($probe['streams'] ?? [] as $stream) {
465	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
466	                    $duration = $stream['duration'];
467	                    break;
468	                }
469	            }
470	        }
471	
472	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
473	    }
474	
475	    private function makeTmpFile(string $prefix, string $suffix): string
476	    {
477	        $path = tempnam(sys_get_temp_dir(), $prefix);
478	        if (! $path) {
479	            throw new \RuntimeException("Failed to create temp file ({$prefix}).");
480	        }
481	
482	        // Rename to add the desired extension so FFmpeg knows the container.
483	        $withExt = $path.$suffix;
484	        rename($path, $withExt);
485	
486	        return $withExt;
487	    }
488	
489	    /**
490	     * Run a pre-escaped shell command via Symfony Process and return its output.
491	     * $exitCode is set by reference.
492	     *
493	     * All arguments in $cmd must be escaped by the caller via
494	     * escapeshellcmd()/escapeshellarg() before this method is called.
495	     * No timeout is applied — video encoding can be arbitrarily long.
496	     */
497	    private function runCommand(string $cmd, ?int &$exitCode = null): string
498	    {
499	        $process = Process::fromShellCommandline($cmd);
500	        $process->setTimeout(null);
501	        $process->run();
502	
503	        $exitCode = $process->getExitCode() ?? 0;
504	
505	        // Callers append 2>&1, so all output (including stderr) is in stdout
506	        return $process->getOutput();
507	    }
508	
509	    private function removeDir(string $dir): void
510	    {
511	        if (! is_dir($dir)) {
512	            return;
513	        }
514	
515	        foreach (scandir($dir) ?: [] as $file) {
516	            if ($file === '.' || $file === '..') {
517	                continue;
518	            }
519	            $path = "{$dir}/{$file}";
520	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
521	        }
522	
523	        @rmdir($dir);
524	    }
525	
526	    /**
527	     * Legacy jobs may pass the original file path instead of the media directory.
528	     * Normalize to the directory prefix expected by allFiles().
529	     */
530	    private function normalizeVideoCleanupBasePath(string $basePath): string
531	    {
532	        $normalized = trim($basePath);
533	        if ($normalized === '') {
534	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
535	        }
536	
537	        $leaf = basename($normalized);
538	        if (str_contains($leaf, '.')) {
539	            $normalized = dirname($normalized);
540	        }
541	
542	        $normalized = trim($normalized, '/');
543	        if ($normalized === '' || $normalized === '.') {
544	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
545	        }
546	
547	        return $normalized;
548	    }
549	
550	    private function diskName(): string
551	    {
552	        $configured = (string) config('sidest.media_disk', 'media');
553	
554	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
555	        // but injects platform env vars directly into the process environment at runtime,
556	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
557	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
558	        if (is_string($explicit) && trim($explicit) !== '') {
559	            return $configured;
560	        }
561	
562	        if ($configured === 'media') {
563	            $default = (string) config('filesystems.default', 'local');
564	            $defaultConfig = config("filesystems.disks.{$default}");
565	
566	            if (
567	                $default !== '' &&
568	                $default !== 'local' &&
569	                $default !== 'media' &&
570	                is_array($defaultConfig) &&
571	                (($defaultConfig['driver'] ?? null) === 's3')
572	            ) {
573	                return $default;
574	            }
575	        }
576	
577	        return $configured;
578	    }
579	
580	    private function disk(): \Illuminate\Contracts\Filesystem\Filesystem
581	    {
582	        return Storage::disk($this->diskName());
583	    }
584	
585	    private function ffmpegBinary(): string
586	    {
587	        return (string) config('sidest.ffmpeg_binary', 'ffmpeg');
588	    }
589	
590	    private function ffprobeBinary(): string
591	    {
592	        return (string) config('sidest.ffprobe_binary', 'ffprobe');
593	    }
594	}
