235	     *   ?ids[]=uuid,...                optional: return only specific media items (for polling)
236	     */
237	    public function index(): JsonResponse
238	    {
239	        $pro = $this->currentProfessional(request());
240	        $pro->loadMissing('site');
241	        $site = $this->currentSite($pro);
242	
243	        $rawMediaType = strtolower(trim((string) request()->input('media_type', 'image')));
244	        $mediaTypeFilter = in_array($rawMediaType, ['image', 'video', 'all'], true) ? $rawMediaType : 'image';
245	
246	        $query = SiteMedia::query()
247	            ->where('site_id', $site->id)
248	            ->where('is_active', true)
249	            ->orderBy('pool')
250	            ->orderBy('sort_order')
251	            ->orderBy('created_at');
252	
253	        if ($mediaTypeFilter !== 'all') {
254	            $query->where('media_type', $mediaTypeFilter);
255	        }
256	
257	        if (request()->has('pool')) {
258	            $pool = strtolower(trim(request()->input('pool')));
259	            if (in_array($pool, ['gallery', 'content'], true)) {
260	                $query->where('pool', $pool);
261	            }
262	        }
263	
264	        // Efficient polling: return only the requested IDs.
265	        if (request()->has('ids')) {
266	            $ids = array_filter((array) request()->input('ids'), fn ($id) => is_string($id) && Str::isUuid($id));
267	            if (! empty($ids)) {
268	                $query->whereIn('id', array_values($ids));
269	            }
270	        }
271	
272	        $query->with('mediaVariants');
273	
274	        $items = $query->get()->map(fn (SiteMedia $item) => $this->buildMediaPayload($item, includeVariants: true));
275	
276	        return $this->success([
277	            'images' => $items,
278	            'limits' => [
279	                'gallery' => config('sidest.image_pools.gallery.max', 5),
280	                'content' => config('sidest.image_pools.content.max', 5),
281	            ],
