285	    /**
286	     * Reorder active media for a specific pool.
287	     *
288	     * POST /api/images/reorder
289	     *   { pool: gallery|content, media_type?: image|video, ids: [uuid, ...] }
290	     *
291	     * Scope is pool + optional media_type:
292	     *   - `media_type` provided → reorder only items of that type (legacy
293	     *     behaviour; kept so Content panel's image-only + video-only reorders
294	     *     still work).
295	     *   - `media_type` omitted → reorder the *entire pool* across media types.
296	     *     Required for the unified affiliate gallery grid where photos and
297	     *     videos share one ordered list of 6 slots.
298	     */
299	    public function reorder(ReorderPoolImagesRequest $request): JsonResponse
300	    {
301	        $pro = $this->currentProfessional($request);
302	        $pro->loadMissing('site');
303	        $site = $this->currentSite($pro);
304	
305	        $pool = $request->validated('pool');
306	        // null here = mixed-type reorder (unified grid). Don't default to
307	        // 'image' — that silently drops video ids and corrupts the order.
308	        $mediaType = $request->validated('media_type');
309	        $ids = array_values(array_unique($request->validated('ids') ?? []));
310	
311	        DB::transaction(function () use ($site, $pool, $mediaType, $ids) {
312	            if (DB::getDriverName() === 'pgsql') {
313	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
314	            }
315	
316	            $siteImages = SiteMedia::query()
317	                ->where('site_id', $site->id)
318	                ->lockForUpdate()
319	                ->orderBy('sort_order')
320	                ->orderBy('created_at')
321	                ->get(['id', 'pool', 'media_type', 'sort_order', 'is_active']);
322	
323	            $targetImages = $siteImages
324	                ->where('is_active', true)
325	                ->where('pool', $pool)
326	                ->when($mediaType !== null, fn ($c) => $c->where('media_type', $mediaType))
327	                ->values();
328	
329	            if ($targetImages->isEmpty()) {
330	                abort(422, 'No active media found in this pool.');
331	            }
332	
333	            $targetIds = $targetImages->pluck('id')->all();
334	            $targetSet = array_flip($targetIds);
335	
336	            foreach ($ids as $id) {
337	                if (! isset($targetSet[$id])) {
338	                    abort(422, 'One or more media items are invalid.');
339	                }
340	            }
341	
342	            $remainingTargetIds = array_values(array_diff($targetIds, $ids));
343	            $reorderedTargetIds = array_merge($ids, $remainingTargetIds);
344	
345	            $finalIds = $siteImages->pluck('id')->all();
346	            $targetPositions = [];
347	
348	            foreach ($siteImages as $index => $image) {
349	                $matchesPool = $image->is_active && $image->pool === $pool;
350	                $matchesType = $mediaType === null || $image->media_type === $mediaType;
351	                if ($matchesPool && $matchesType) {
352	                    $targetPositions[] = $index;
353	                }
354	            }
355	
356	            foreach ($targetPositions as $index => $position) {
357	                $finalIds[$position] = $reorderedTargetIds[$index];
358	            }
359	
360	            $offset = $siteImages->count() + 1000;
361	
362	            foreach ($finalIds as $index => $id) {
363	                SiteMedia::query()
364	                    ->where('site_id', $site->id)
365	                    ->where('id', $id)
366	                    ->update(['sort_order' => $offset + $index]);
367	            }
368	
369	            foreach ($finalIds as $index => $id) {
370	                SiteMedia::query()
371	                    ->where('site_id', $site->id)
372	                    ->where('id', $id)
373	                    ->update(['sort_order' => $index]);
374	            }
375	        });
376	
377	        app(SiteCacheService::class)->invalidateSite($site);
378	
379	        return $this->success(['ok' => true]);
380	    }
