3	namespace App\Services\Media;
4	
5	use App\Models\Core\MediaVariant;
6	use App\Models\Core\Site\SiteMedia;
7	use Illuminate\Support\Facades\Log;
8	use Illuminate\Support\Facades\Storage;
9	use Symfony\Component\Process\Process;
10	
11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/sidest.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (SIDEST_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /* ------------------------------------------------------------------ */
43	    /*  Public API */
44	    /* ------------------------------------------------------------------ */
45	
46	    /**
47	     * Run FFprobe on a local file and return metadata array.
48	     * Throws \RuntimeException if the binary fails.
49	     *
50	     * @return array<string, mixed>
51	     */
52	    public function probe(string $localPath): array
53	    {
54	        $ffprobe = $this->ffprobeBinary();
55	        $cmd = sprintf(
56	            '%s -v quiet -print_format json -show_format -show_streams %s 2>&1',
57	            escapeshellcmd($ffprobe),
58	            escapeshellarg($localPath),
59	        );
60	
61	        $output = $this->runCommand($cmd, $exitCode);
62	
63	        if ($exitCode !== 0) {
64	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$output}");
65	        }
66	
67	        $data = json_decode($output, true);
68	        if (! is_array($data)) {
69	            throw new \RuntimeException('ffprobe returned non-JSON output.');
70	        }
71	
72	        return $data;
73	    }
74	
75	    /**
76	     * Probe a local file and validate it contains at least one video stream.
77	     *
78	     * Call this in the upload controller before storing to R2 so malformed
79	     * containers are rejected at the HTTP boundary, not on the worker.
80	     *
81	     * @return array<string, mixed> Raw ffprobe data (reuse to avoid a second probe).
82	     * @throws \RuntimeException if the container is unreadable or has no video stream.
83	     */
84	    public function probeAndValidate(string $localPath): array
85	    {
86	        $probe = $this->probe($localPath);
87	
88	        $hasVideoStream = false;
89	        foreach ($probe['streams'] ?? [] as $stream) {
90	            if (($stream['codec_type'] ?? '') === 'video') {
91	                $hasVideoStream = true;
92	                break;
93	            }
94	        }
95	
96	        if (! $hasVideoStream) {
97	            throw new \RuntimeException('File does not contain a recognisable video stream.');
98	        }
99	
100	        return $probe;
101	    }
102	
103	    /**
104	     * Process a video original into all configured artifacts.
105	     *
106	     * @throws \RuntimeException on unrecoverable processing errors
107	     */
108	    public function processVariants(
109	        string $localOriginalPath,
110	        string $mediaId,
111	        string $basePath,
112	    ): void {
113	        Log::info('VideoVariantService: starting', [
114	            'media_id' => $mediaId,
115	            'base_path' => $basePath,
116	        ]);
117	
118	        // --- 1. Probe metadata ---
119	        $probe = $this->probe($localOriginalPath);
120	        $durationMs = $this->extractDurationMs($probe);
121	        $maxDur = (int) config('sidest.video_max_duration_seconds', 300);
122	
123	        if ($durationMs > $maxDur * 1000) {
124	            throw new \RuntimeException(
125	                "Video duration ({$durationMs}ms) exceeds maximum ({$maxDur}s)."
126	            );
127	        }
128	
129	        $variantDefs = (array) config('sidest.video_variants', []);
130	        $tmpDirs = [];
131	
132	        try {
133	            // --- 2 & 3. Encode MP4 variants ---
134	            $mp4Paths = [];
135	            foreach ($variantDefs as $variantKey => $def) {
136	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
137	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def);
138	                $mp4Paths[$variantKey] = $tmpMp4;
139	            }
140	
141	            // --- 4. Package HLS from each MP4 ---
142	            $hlsDirs = [];
143	            foreach ($mp4Paths as $variantKey => $mp4) {
144	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
145	                if (! mkdir($tmpHlsDir, 0755, true)) {
146	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
147	                }
148	                $tmpDirs[] = $tmpHlsDir;
149	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8');
150	                $hlsDirs[$variantKey] = $tmpHlsDir;
151	            }
152	
153	            // --- 5. Build adaptive master playlist ---
154	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
155	
156	            // --- 6. Extract poster ---
157	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
158	            $this->extractPoster($localOriginalPath, $tmpPoster);
159	
160	            // --- 7. Upload all artifacts ---
161	            $disk = $this->disk();
162	            $diskName = $this->resolvedDiskName();
163	
164	            // Upload MP4s
165	            foreach ($mp4Paths as $variantKey => $mp4) {
166	                $remotePath = "{$basePath}/{$variantKey}.mp4";
167	                $stream = fopen($mp4, 'rb');
168	                $disk->put($remotePath, $stream, 'public');
169	                if (is_resource($stream)) {
170	                    fclose($stream);
171	                }
172	
173	                $def = $variantDefs[$variantKey] ?? [];
174	                // Unique key: (media_id, variant_key, artifact_type)
175	                MediaVariant::updateOrCreate(
176	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
177	                    [
178	                        'disk' => $diskName,
179	                        'path' => $remotePath,
180	                        'mime' => 'video/mp4',
181	                        'bitrate_kbps' => (int) ($def['video_bitrate_kbps'] ?? 0) + (int) ($def['audio_bitrate_kbps'] ?? 0),
182	                        'file_size_bytes' => filesize($mp4) ?: null,
183	                        'duration_ms' => $durationMs,
184	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
185	                    ]
186	                );
187	            }
188	
189	            // Upload HLS segments + playlists
190	            foreach ($hlsDirs as $variantKey => $hlsDir) {
191	                $remoteHlsBase = "{$basePath}/hls/{$variantKey}";
192	                foreach (scandir($hlsDir) ?: [] as $file) {
193	                    if ($file === '.' || $file === '..') {
194	                        continue;
195	                    }
196	                    $localFile = "{$hlsDir}/{$file}";
197	                    $remotePath = "{$remoteHlsBase}/{$file}";
198	                    $mime = str_ends_with($file, '.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp2t';
199	                    $stream = fopen($localFile, 'rb');
200	                    $disk->put($remotePath, $stream, ['visibility' => 'public', 'ContentType' => $mime]);
201	                    if (is_resource($stream)) {
202	                        fclose($stream);
203	                    }
204	                }
205	
206	                $playlistPath = "{$remoteHlsBase}/playlist.m3u8";
207	                $def = $variantDefs[$variantKey] ?? [];
208	                MediaVariant::updateOrCreate(
209	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'hls_playlist'],
210	                    [
211	                        'disk' => $diskName,
212	                        'path' => $playlistPath,
213	                        'mime' => 'application/vnd.apple.mpegurl',
214	                        'duration_ms' => $durationMs,
215	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
216	                    ]
217	                );
218	            }
219	
220	            // Upload adaptive master playlist
221	            $adaptiveRemotePath = "{$basePath}/hls/adaptive.m3u8";
222	            $disk->put($adaptiveRemotePath, $adaptiveContent, [
223	                'visibility' => 'public',
224	                'ContentType' => 'application/vnd.apple.mpegurl',
225	            ]);
226	
227	            MediaVariant::updateOrCreate(
228	                ['media_id' => $mediaId, 'variant_key' => 'adaptive', 'artifact_type' => 'hls_playlist'],
229	                [
230	                    'disk' => $diskName,
231	                    'path' => $adaptiveRemotePath,
232	                    'mime' => 'application/vnd.apple.mpegurl',
233	                ]
234	            );
235	
236	            // Upload poster
237	            $posterRemotePath = "{$basePath}/poster.jpg";
238	            $stream = fopen($tmpPoster, 'rb');
239	            $disk->put($posterRemotePath, $stream, ['visibility' => 'public', 'ContentType' => 'image/jpeg']);
240	            if (is_resource($stream)) {
241	                fclose($stream);
242	            }
243	
244	            MediaVariant::updateOrCreate(
245	                ['media_id' => $mediaId, 'variant_key' => 'poster', 'artifact_type' => 'poster'],
246	                [
247	                    'disk' => $diskName,
248	                    'path' => $posterRemotePath,
249	                    'mime' => 'image/jpeg',
250	                    'file_size_bytes' => filesize($tmpPoster) ?: null,
251	                ]
252	            );
253	
254	            // --- 8. Update SiteMedia ---
255	            SiteMedia::query()
256	                ->where('id', $mediaId)
257	                ->whereNull('deleted_at')
258	                ->update([
259	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
260	                    'processing_error' => null,
261	                    'duration_ms' => $durationMs,
262	                    'poster_path' => $posterRemotePath,
263	                ]);
264	
265	            Log::info('VideoVariantService: completed', [
266	                'media_id' => $mediaId,
267	                'duration_ms' => $durationMs,
268	            ]);
269	        } finally {
270	            // Cleanup temp files and dirs
271	            foreach ($mp4Paths ?? [] as $mp4) {
272	                if (file_exists($mp4)) {
273	                    @unlink($mp4);
274	                }
275	            }
276	            if (isset($tmpPoster) && file_exists($tmpPoster)) {
277	                @unlink($tmpPoster);
