695	    /**
696	     * Build a media item payload array suitable for API responses.
697	     *
698	     * @param  bool  $includeVariants  Whether to include resolved variant/stream maps.
699	     * @return array<string, mixed>
700	     */
701	    private function buildMediaPayload(SiteMedia $media, bool $includeVariants = false): array
702	    {
703	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
704	        $isReady = $media->processing_state === SiteMedia::PROCESSING_STATE_READY;
705	        $isProcessing = $media->processing_state === SiteMedia::PROCESSING_STATE_PENDING
706	            || $media->processing_state === SiteMedia::PROCESSING_STATE_PROCESSING;
707	
708	        $payload = [
709	            'id' => $media->id,
710	            'pool' => $media->pool,
711	            'alt_text' => $media->alt_text,
712	            'caption' => $media->caption,
713	            'sort_order' => $media->sort_order,
714	            'media_type' => $media->media_type,
715	            'processing_state' => $media->processing_state,
716	            'processing' => $isProcessing, // backward-compat boolean
717	            'processing_error' => $media->processing_error,
718	            'created_at' => $media->created_at,
719	            'updated_at' => $media->updated_at,
720	        ];
721	
722	        if ($isVideo) {
723	            $payload['duration_ms'] = $media->duration_ms;
724	            $payload['poster'] = null;
725	        }
726	
727	        if (! $includeVariants) {
728	            return $payload;
729	        }
730	
731	        if ($isVideo) {
732	            if ($isReady) {
733	                $mvList = $media->relationLoaded('mediaVariants')
734	                    ? $media->mediaVariants
735	                    : $media->mediaVariants()->get();
736	
737	                $variants = [];
738	                $streams = [];
739	                $poster = null;
740	
741	                foreach ($mvList as $mv) {
742	                    if ($mv->artifact_type === 'mp4') {
743	                        $variants[$mv->variant_key] = $mv->url;
744	                    } elseif ($mv->artifact_type === 'hls_playlist') {
745	                        $streams[$mv->variant_key] = $mv->url;
746	                    } elseif ($mv->artifact_type === 'poster') {
747	                        $poster = $mv->url;
748	                    }
749	                }
750	
751	                $payload['variants'] = $variants;
752	                $payload['streams'] = $streams;
753	                $payload['poster'] = $poster;
754	            } else {
755	                $payload['variants'] = [];
756	                $payload['streams'] = [];
757	                $payload['poster'] = null;
758	            }
759	        } else {
760	            $payload['variants'] = $isReady ? $media->variantUrls() : [];
761	        }
762	
763	        return $payload;
764	    }
765	}
